const fn = new Function(code + "\nreturn { abortableDelay };");
const { abortableDelay } = fn();
const out = await abortableDelay(10, new AbortController().signal);
if (out !== "done") throw new Error("An un-aborted delay resolves with 'done'.");

const fn = new Function(code + "\nreturn { abortableDelay };");
const { abortableDelay } = fn();
const c = new AbortController();
const p = abortableDelay(60, c.signal);
setTimeout(() => c.abort(), 5);
let err;
try { await p; } catch (e) { err = e; }
if (!err || err.name !== "AbortError") throw new Error("Mid-flight abort must reject with err.name === 'AbortError'.");

